-- MakerWorld free-to-sell: clean titles + rewrite descriptions/story/bio
UPDATE products SET title='Articulated Frog', description='Katak artikulasi fleksibel dengan gerakan tubuh yang mengalir. Seru untuk dimainkan dan dipajang, tersedia varian satu warna hingga tiga warna.', story='Katak artikulasi ini dirancang dengan ruas-ruas yang bisa digerakkan, cocok untuk mainan meja maupun koleksi dekoratif. Pilih versi satu warna untuk tampilan minimalis, atau variasi dua hingga tiga warna untuk aksen yang lebih hidup.', artists='[]' WHERE slug='3d-frog';
UPDATE products SET title='Articulated Duck', description='Bebek artikulasi yang lentur dan menggemaskan. Cocok untuk dekorasi meja, mainan anak, atau hadiah.', story='Sosok bebek lucu dengan badan yang bisa digoyang ke sana kemari. Dicetak dari material PLA favorit, opsi satu warna untuk hasil bersih atau tambahan warna pada mata agar lebih menonjol.', artists='[]' WHERE slug='3d-duck';
UPDATE products SET title='Happy Carrot', description='Wortel tersenyum yang berdiri tegak. Hadiah kecil yang lucu untuk meja, rak, dan balkon.', story='Wortel dengan wajah ceria ini membawa keceriaan ke mana pun diletakkan. Cetakan tunggal yang cepat dan hemat, pas untuk hadiah tanpa kata.', artists='[]' WHERE slug='3d-carrot';
UPDATE products SET title='Flexi Lizard', description='Kadal fleksibel yang seru untuk dimainkan dan dipamerkan. Detail presisi dengan hasil lapisan halus.', story='Kadal dengan lekuk tubuh yang lentur dan ekor yang bisa digoyang. Profil lapisan tipis memberikan hasil detail yang rapi di seluruh permukaan.', artists='[]' WHERE slug='3d-lizard';
UPDATE products SET title='Flexi Christmas Tree Ornament', description='Pohon natal mini yang lentur, cocok untuk dekorasi rumah dan hadiah akhir tahun.', story='Ornamen pohon natal dengan badan fleksibel yang bisa dimiring-condongkan. Bentuknya ringan dan cepat dicetak, siap menghiasi meja atau menggantung di pohon.', artists='[]' WHERE slug='3d-flexi-christmas-tree';
UPDATE products SET title='Small Mesh Catch-All Bowl', description='Mangkuk mesh kecil untuk kunci, koin, dan aksesoris. Desain anyaman terbuka yang cantik.', story='Bowl kecil bertekstur mesh yang menjadi penampung pernak-pernik harian. Desain permukaan terbuka membuat tampilan ringan dan modern, pas di meja masuk atau ruang kerja.', artists='[]' WHERE slug='3d-mesh-bowl';
UPDATE products SET title='Tiger Hype Necklace', description='Kalung harimau hype bergaya streetwear. Bisa dicetak satu warna atau dua warna untuk tampilan lebih berani.', story='Kalung dengan motif kepala harimau yang vibrant. Memadukan gaya street art dan detail presisi; satu warna untuk simpel, dua warna untuk kontras yang mencolok.', artists='[]' WHERE slug='3d-tiger-necklace';
UPDATE products SET title='Flexi Monster', description='Monster lucu berbadan fleksibel. Menyenangkan untuk dimainkan dan dihadiahkan ke anak-anak.', story='Monster ramah dengan ruas badan fleksibel yang bisa diayunkan. Mudah dicetak satu warna dengan hasil rapi, jadi teman meja yang menghibur.', artists='[]' WHERE slug='3d-flexi-monster';
UPDATE products SET title='Flexi Unicorn', description='Unicorn fleksibel yang cerah dan playful. Favorit untuk mainan dan kado anak-anak.', story='Unicorn lucu dengan tanduk ikonik dan badan yang bisa digeliatkan. Pilih satu warna untuk tampilan bersih atau multi-warna agar aksennya makin hidup.', artists='[]' WHERE slug='3d-flexi-unicorn';
UPDATE products SET title='Flexi Bear', description='Beruang fleksibel yang menggemaskan, lengkap dengan varian gantungan kunci.', story='Beruang fleksibel versi penuh yang lentur, atau varian gantungan kunci untuk aksesori harian. Profil cetak cepat dengan hasil tetap rapi.', artists='[]' WHERE slug='3d-flexi-bear';
UPDATE products SET title='Hex Drip Tray', description='Wadah hexagonal untuk pernak-pernik dan alat tulis kecil. Bentuk tegas dengan celah yang praktis.', story='Tray berlubang heksagonal yang dirancang untuk menampung barang kecil di meja kerja. Cetakannya ringan dan cepat selesai, praktis untuk ruang kerja maupun dapur.', artists='[]' WHERE slug='3d-hex-drip';
UPDATE products SET title='Flexi Wiggle Worm', description='Uler flexi yang menggeliat, bisa dicetak satu warna atau multi warna.', story='Cacing dengan segmen fleksibel yang bergerak-gerak penuh karakter. Versi multi warna menghidupkan pola tubuh yang menarik dalam satu proses cetak.', artists='[]' WHERE slug='3d-flexi-worm';
UPDATE products SET title='Valentine Gear Fidget', description='Spinner gear fidget yang bikin betah bermain. Berputar mulus dan menenangkan.', story='Fidget berbentuk gear yang bisa diputar-putar tanpa henti. Hadiah praktis yang membantu fokus dan menghilangkan kebosanan di meja.', artists='[]' WHERE slug='3d-valentine-gear';
UPDATE products SET title='Valentine Infinity Cube', description='Kubus infinity untuk fidget penghilang penat dengan nuansa valentine.', story='Kubus yang bisa diputar tanpa akhir untuk mengurangi kebosanan saat belajar atau bekerja. Sentuhan nuansa valentine menjadikannya kado yang tulus dan berguna.', artists='[]' WHERE slug='3d-valentine-cube';
UPDATE products SET title='Modern Spiral Catch-All Bowl', description='Mangkuk spiral modern untuk pernak-pernik meja dengan alur memutar yang anggun.', story='Permukaan spiral yang halus memberikan tekstur visual yang elegan. Pilihan tepat untuk menyimpan aksesori kecil di ruang tidur atau ruang tamu.', artists='[]' WHERE slug='3d-spiral-bowl';
UPDATE products SET title='Mini Articulated Dinosaur', description='Dino mini artikulasi, lucu dan mudah dicetak satu atau dua warna.', story='Dinosaurus mini dengan anggota tubuh yang bisa digerakkan, sudah jadi favorit kolektor. Bisa dicetak satu warna atau multi warna pada plate terpisah.', artists='[]' WHERE slug='3d-mini-dino';
UPDATE products SET title='Wave Catch-All Tray', description='Nampan dengan lekukan ombak yang penuh irama untuk menaruh pernak-pernik.', story='Tray dengan tepi bergelombang ringan, tampil modern di meja kerja atau konsol. Bentuk ombak yang mengalir memberi kesan tenang pada ruangan.', artists='[]' WHERE slug='3d-wave-tray';
UPDATE products SET title='Spiral Catch-All Tray', description='Nampan spiral yang anggun untuk meja dan rak, sempurna untuk aksesoris kecil.', story='Nampan dengan alur spiral yang mengalir halus. Cocok di meja masuk, rak, atau meja rias untuk menata aksesoris kecil.', artists='[]' WHERE slug='3d-spiral-tray';
UPDATE products SET title='Daisy Magnets', description='Set magnet bunga daisy berwarna-warni untuk kulkas dan papan tulis.', story='Kumpulan magnet bunga daisy dengan warna ceria untuk menempelkan foto dan catatan. Ukuran kecil dan besar, gampang dipasang di dapur atau papan.', artists='[]' WHERE slug='3d-daisy-magnets';
UPDATE products SET title='Flexi Flying Fox', description='Kelelawar rubah terbang yang lentur dan dramatis saat digoyang.', story='Flying fox dengan sayap lebar dan badan fleksibel yang bergerak bebas. Saat digoyang, tampak seperti sedang terbang lancar di udara.', artists='[]' WHERE slug='3d-flexi-fox';
